// Parse RSS XML and extract items
const xml2js = require('xml2js');
const parser = new xml2js.Parser();

const results = [];
const seenTitles = new Set();

for (const item of items) {
  try {
    const xmlData = item.json.data;
    const parsed = await parser.parseStringPromise(xmlData);
    const channel = parsed.rss?.channel?.[0];

    if (channel && channel.item) {
      for (const rssItem of channel.item.slice(0, 5)) {
        const title = rssItem.title?.[0] || '';

        // Skip duplicates
        if (seenTitles.has(title)) continue;
        seenTitles.add(title);

        const link = rssItem.link?.[0] || '';
        const description = rssItem.description?.[0] || '';
        const pubDate = rssItem.pubDate?.[0] || new Date().toISOString();

        // Extract image from description or enclosure
        let image = '';
        const enclosure = rssItem.enclosure?.[0];
        if (enclosure && enclosure.$) {
          image = enclosure.$.url || '';
        }
        if (!image) {
          const imgMatch = description.match(/<img[^>]+src="([^"]+)"/i);
          if (imgMatch) image = imgMatch[1];
        }
        if (!image) {
          image = 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=800';
        }

        // Clean description (remove HTML tags)
        const cleanDescription = description.replace(/<[^>]*>/g, '').trim();

        results.push({
          json: {
            title: title,
            link: link,
            excerpt: cleanDescription.substring(0, 200) + '...',
            image: image,
            pubDate: pubDate,
            source: link.includes('vnexpress') ? 'VnExpress' : 
                   link.includes('cafef') ? 'CafeF' : 'NhaDatViet'
          }
        });
      }
    }
  } catch (e) {
    console.error('Parse error:', e.message);
  }
}

// Return only the 3 newest unique items
return results.slice(0, 3);

// Combine all AI outputs with original data
const originalData = $('Split Into Batches').first().json;
const categoryData = $('AI Categorize & Link Projects').first().json;
const rewrittenContent = $('AI Rewrite Content').first().json;

// Parse category JSON safely
let parsed = {};
try {
  const categoryText = categoryData.message?.content || categoryData.content || '{}';
  // Extract JSON from the response
  const jsonMatch = categoryText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  parsed = {
    category: 'Kiến Thức',
    relatedProjects: [],
    summary: []
  };
}

// Format date
const now = new Date();
const formattedDate = `${now.getDate().toString().padStart(2, '0')}/${(now.getMonth() + 1).toString().padStart(2, '0')}/${now.getFullYear()}`;

return {
  json: {
    title: originalData.title,
    image: originalData.image,
    category: parsed.category || 'Kiến Thức',
    date: formattedDate,
    excerpt: originalData.excerpt,
    content: rewrittenContent.message?.content || rewrittenContent.content || originalData.excerpt,
    author: 'Thạch Vũ AI',
    source: originalData.source,
    sourceUrl: originalData.link,
    relatedProjects: parsed.relatedProjects || [],
    aiSummary: parsed.summary || []
  }
};

// Decode current articles.json
const currentFile = JSON.parse(Buffer.from(items[0].json.content, 'base64').toString('utf-8'));
const newsList = currentFile.newsData || [];
const projectList = currentFile.projectData || [];

// Get new article data from previous node
const newArticle = $('Combine AI Results').first().json;

// Check for duplicates by title
const titleExists = newsList.some(article => 
  article.title.toLowerCase().trim() === newArticle.title.toLowerCase().trim()
);

if (titleExists) {
  // Skip duplicate
  return {
    json: {
      skip: true,
      message: 'Duplicate article detected'
    }
  };
}

// Map related project names to project IDs
const relatedProjectIds = [];
if (newArticle.relatedProjects && newArticle.relatedProjects.length > 0) {
  for (const projectName of newArticle.relatedProjects) {
    const matchedProject = projectList.find(p => 
      p.title.toLowerCase().includes(projectName.toLowerCase())
    );
    if (matchedProject) {
      relatedProjectIds.push(matchedProject.id);
    }
  }
}

// Generate new ID
const maxId = newsList.reduce((max, article) => Math.max(max, article.id || 0), 0);

// Create new article object
const newItem = {
  id: maxId + 1,
  title: newArticle.title,
  image: newArticle.image,
  category: newArticle.category,
  date: newArticle.date,
  excerpt: newArticle.excerpt,
  content: newArticle.content,
  author: newArticle.author,
  source: newArticle.source,
  sourceUrl: newArticle.sourceUrl,
  relatedProjects: relatedProjectIds,
  aiSummary: newArticle.aiSummary
};

// Add to beginning of news array
currentFile.newsData = [newItem, ...newsList];

// Keep only last 100 articles
if (currentFile.newsData.length > 100) {
  currentFile.newsData = currentFile.newsData.slice(0, 100);
}

return {
  json: {
    skip: false,
    content: Buffer.from(JSON.stringify(currentFile, null, 4)).toString('base64'),
    message: `Auto-add: ${newArticle.title.substring(0, 50)}...`,
    sha: items[0].json.sha
  }
};
